  wake=context.getSystemService(android.os.PowerManager.class).newWakeLock(android.os.PowerManager.PARTIAL_WAKE_LOCK,"Papers:peer-transfer");wake.acquire(30*60*1000L);if(route.equals("/v1/files/shares")&&method.equals("GET")){JSONArray list=new JSONArray();for(File root:roots())list.put(entry(root,grant));json(output,200,new JSONObject().put("ok",true).put("protocol",1).put("owner",owner).put("entries",list).put("capabilities",new JSONObject().put("changes",true).put("edits",false)));return;}
