  String backpack=uuid(grant.getString("deviceId")+"|proxima");if(route.equals("/v1/backpacks")&&method.equals("GET")){json(output,200,new JSONObject().put("ok",true).put("owner",owner).put("entries",new JSONArray().put(new JSONObject().put("id",backpack).put("name","Proxima").put("kind","proxima"))));return;}
  if(route.startsWith("/v1/backpacks/"+backpack+"/")){String action=route.substring(route.lastIndexOf('/')+1);if(!(action.equals("snapshot")&&method.equals("GET")||(action.equals("commands")||action.equals("replace"))&&method.equals("POST")))throw new IOException("Unsupported method.");JSONObject request=new JSONObject().put("operation",action.equals("commands")?"command":action.equals("replace")?"replace":"snapshot");if(action.equals("commands"))request.put("command",body(input,length));else if(action.equals("replace")){JSONObject data=body(input,length);request.put("snapshot",data.has("snapshot")?data.getJSONObject("snapshot"):data.has("projection")?data.getJSONObject("projection"):data).put("from",grant.getJSONObject("pc").getString("name"));if(data.has("expectedSeq"))request.put("expectedSeq",data.getLong("expectedSeq"));}else if(!action.equals("snapshot"))throw new IOException("Unsupported Backpack route.");JSONObject result=proxima(request);result.put("ok",true).put("owner",owner).put("resourceId",backpack).put("kind","proxima").put("events",true);json(output,200,result);return;}
  String workspace=uuid(grant.getString("deviceId")+"|ayg");if(route.equals("/v1/workspaces")&&method.equals("GET")){json(output,200,new JSONObject().put("ok",true).put("owner",owner).put("entries",new JSONArray().put(new JSONObject().put("id",workspace).put("name","As you Go").put("kind","as-you-go"))));return;}
  if(route.equals("/v1/workspaces/"+workspace+"/state")){JSONObject loaded=(JSONObject)files.call(new JSONObject().put("operation","local-state-load"));if(method.equals("GET")){String state=loaded.optString("state","");json(output,200,new JSONObject().put("ok",true).put("state",PhoneStorage.map(state.isEmpty()?new JSONObject().put("schemaVersion",1).put("groups",new JSONArray()).put("shortcuts",new JSONArray()):new JSONObject(state),true)).put("sharedRoots",new JSONArray(roots().stream().map(PhoneStorage::name).toArray())).put("revision",loaded.getString("revision")));}else{if(!method.equals("POST"))throw new IOException("Unsupported workspace method.");JSONObject data=body(input,length,64*1024*1024);JSONObject saved=(JSONObject)files.call(new JSONObject().put("operation","local-state-save").put("state",PhoneStorage.map(new JSONObject(data.getString("state")),false).toString()).put("revision",data.getString("revision")));json(output,200,new JSONObject().put("ok",true).put("save",saved));}return;}
