  if(action.equals("preview")){JSONObject preview=new JSONObject().put("kind","none");if(file.isFile()&&file.length()<2*1024*1024&&file.getName().matches("(?i).*\\.(txt|md|json|csv|log|js|css|html|xml)$"))preview=new JSONObject().put("kind","text").put("text",new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)).put("eof",true);json(output,200,new JSONObject().put("ok",true).put("preview",preview));return;}
  String version=headers.getOrDefault("if-match","");if(!version.matches("\"[a-f0-9]{64}\"")){json(output,428,new JSONObject().put("ok",false).put("code","VERSION_REQUIRED"));return;}check(file,grant,version.substring(1,65));if(!file.isFile())throw new IOException("Choose a file.");
